+type ChildAccessor<T> = (data: T) => Iterable<T> | null | undefined;
+
+export interface HierarchyNode<T> {
+  data: T;
+  depth: number;
+  height: number;
+  parent: HierarchyNode<T> | null;
+  children?: HierarchyNode<T>[];
+  value?: number;
+  sort(compare: (a: HierarchyNode<T>, b: HierarchyNode<T>) => number): this;
+  sum(value: (data: T) => number): this;
+}
+
+export interface HierarchyRectangularNode<T> extends HierarchyNode<T> {
+  x0: number;
+  y0: number;
+  x1: number;
+  y1: number;
+  parent: HierarchyRectangularNode<T> | null;
+  children?: HierarchyRectangularNode<T>[];
+}
+
+export interface ScaleLinear {
+  (value: number): number;
+  domain(): [number, number];
+  domain(value: [number, number]): ScaleLinear;
+  range(): [number, number];
+  range(value: [number, number]): ScaleLinear;
+}
+
+export interface TreemapLayout<T> {
+  (root: HierarchyNode<T>): HierarchyRectangularNode<T>;
+  size(): [number, number];
+  size(value: [number, number]): TreemapLayout<T>;
+  round(): boolean;
+  round(value: boolean): TreemapLayout<T>;
+  paddingInner(): number;
+  paddingInner(value: number): TreemapLayout<T>;
+}
+
+function attachMethods<T>(root: HierarchyNode<T>): void {
+  root.sort = function sort(compare) {
+    sortNode(this, compare);
+    return this;
+  };
+  root.sum = function sum(value) {
+    sumNode(this, value);
+    return this;
+  };
+  root.children?.forEach(attachMethods);
+}
+
+function sortNode<T>(
+  node: HierarchyNode<T>,
+  compare: (a: HierarchyNode<T>, b: HierarchyNode<T>) => number
+): void {
+  if (node.children) {
+    node.children.sort(compare);
+    node.children.forEach((child) => sortNode(child, compare));
+  }
+}
+
+function sumNode<T>(node: HierarchyNode<T>, value: (data: T) => number): number {
+  const ownValue = Math.max(0, Number(value(node.data)) || 0);
+  const childrenValue =
+    node.children?.reduce((total, child) => total + sumNode(child, value), 0) ??
+    0;
+  node.value = ownValue + childrenValue;
+  return node.value;
+}
+
+export function hierarchy<T>(
+  data: T,
+  childrenAccessor?: ChildAccessor<T>
+): HierarchyNode<T> {
+  function build(
+    nodeData: T,
+    parent: HierarchyNode<T> | null,
+    depth: number
+  ): HierarchyNode<T> {
+    const node = {
+      data: nodeData,
+      depth,
+      height: 0,
+      parent,
+      sort: undefined as unknown as HierarchyNode<T>['sort'],
+      sum: undefined as unknown as HierarchyNode<T>['sum']
+    } as HierarchyNode<T>;
+    const children = childrenAccessor?.(nodeData);
+    if (children) {
+      node.children = Array.from(children, (childData) =>
+        build(childData, node, depth + 1)
+      );
+      if (node.children.length) {
+        node.height = Math.max(...node.children.map((child) => child.height)) + 1;
+      } else {
+        delete node.children;
+      }
+    }
+    return node;
+  }
+
+  const root = build(data, null, 0);
+  attachMethods(root);
+  return root;
+}
+
+export function scaleLinear(): ScaleLinear {
+  let domain: [number, number] = [0, 1];
+  let range: [number, number] = [0, 1];
+
+  const scale = ((value: number) => {
+    const [domainStart, domainEnd] = domain;
+    const [rangeStart, rangeEnd] = range;
+    const domainSpan = domainEnd - domainStart;
+    if (domainSpan === 0) {
+      return rangeStart;
+    }
+    return (
+      rangeStart + ((value - domainStart) / domainSpan) * (rangeEnd - rangeStart)
+    );
+  }) as ScaleLinear;
+
+  scale.domain = (value?: [number, number]) => {
+    if (value === undefined) {
+      return domain;
+    }
+    domain = value;
+    return scale;
+  };
+  scale.range = (value?: [number, number]) => {
+    if (value === undefined) {
+      return range;
+    }
+    range = value;
+    return scale;
+  };
+
+  return scale;
+}
+
+export function treemap<T>(): TreemapLayout<T> {
+  let layoutSize: [number, number] = [1, 1];
+  let shouldRound = false;
+  let innerPadding = 0;
+
+  const layout = ((root: HierarchyNode<T>) => {
+    const rectangularRoot = root as HierarchyRectangularNode<T>;
+    layoutNode(rectangularRoot, 0, 0, layoutSize[0], layoutSize[1]);
+    return rectangularRoot;
+  }) as TreemapLayout<T>;
+
+  layout.size = (value?: [number, number]) => {
+    if (value === undefined) {
+      return layoutSize;
+    }
+    layoutSize = value;
+    return layout;
+  };
+  layout.round = (value?: boolean) => {
+    if (value === undefined) {
+      return shouldRound;
+    }
+    shouldRound = value;
+    return layout;
+  };
+  layout.paddingInner = (value?: number) => {
+    if (value === undefined) {
+      return innerPadding;
+    }
+    innerPadding = Math.max(0, value);
+    return layout;
+  };
+
+  function layoutNode(
+    node: HierarchyRectangularNode<T>,
+    x0: number,
+    y0: number,
+    x1: number,
+    y1: number
+  ): void {
+    node.x0 = roundIfNeeded(x0);
+    node.y0 = roundIfNeeded(y0);
+    node.x1 = roundIfNeeded(x1);
+    node.y1 = roundIfNeeded(y1);
+
+    const children = node.children as HierarchyRectangularNode<T>[] | undefined;
+    if (!children?.length) {
+      return;
+    }
+
+    const totalValue = children.reduce(
+      (total, child) => total + Math.max(0, child.value ?? 0),
+      0
+    );
+    const equalShare = totalValue === 0 ? 1 / children.length : 0;
+    const horizontal = x1 - x0 >= y1 - y0;
+    let cursor = horizontal ? x0 : y0;
+    const availableSpan = Math.max(
+      0,
+      (horizontal ? x1 - x0 : y1 - y0) - innerPadding * (children.length - 1)
+    );
+
+    children.forEach((child, index) => {
+      const share = totalValue === 0 ? equalShare : (child.value ?? 0) / totalValue;
+      const childSpan =
+        index === children.length - 1
+          ? Math.max(0, (horizontal ? x1 : y1) - cursor)
+          : availableSpan * share;
+      const nextCursor = cursor + childSpan;
+
+      if (horizontal) {
+        layoutNode(child, cursor, y0, nextCursor, y1);
+      } else {
+        layoutNode(child, x0, cursor, x1, nextCursor);
+      }
+      cursor = nextCursor + innerPadding;
+    });
+  }
+
+  function roundIfNeeded(value: number): number {
+    return shouldRound ? Math.round(value) : value;
+  }
+
+  return layout;
+}
